#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, c, f, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) : y(y), c(c), f(f), cost(cost) {}
};

vector<Edge> edges;
const int MAXN = 14043;
vector<int> graph[MAXN];

long long total_cost = 0;
long long dist[MAXN];
int parent[MAXN], parent_edge[MAXN], inq[MAXN];

const long long INF = 1e18;
int s = MAXN - 2;
int t = MAXN - 1;

int get_residual(int x) {
    return edges[x].c - edges[x].f;
}

void update_flow() {
    for (int i = 0; i < MAXN; i++) {
        dist[i] = INF;
        parent[i] = -1;
        parent_edge[i] = -1;
        inq[i] = 0;
    }
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto e_idx : graph[u]) {
            if (get_residual(e_idx) == 0) continue;
            int cst = edges[e_idx].cost;
            int v = edges[e_idx].y;
            if (dist[v] > dist[u] + cst) {
                dist[v] = dist[u] + cst;
                parent[v] = u;
                parent_edge[v] = e_idx;
                if (inq[v] == 0) {
                    inq[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    int cur = t;
    while (cur != s) {
        edges[parent_edge[cur]].f++;
        edges[parent_edge[cur] ^ 1].f--;
        cur = parent[cur];
    }
    total_cost += dist[t];
}

void add_edge(int from, int to, int cap, int cst) {
    graph[from].push_back(edges.size());
    edges.emplace_back(to, cap, 0, cst);
    graph[to].push_back(edges.size());
    edges.emplace_back(from, 0, 0, -cst);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x;
        add_edge(s, x, 1, 0);
    }
    int tt = 101;
    for (int i = 0; i < tt; i++)
        add_edge(1 + i * n, t, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        for (int j = 0; j < tt - 1; j++) {
            add_edge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            add_edge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < tt - 1; j++)
            add_edge(i + j * n, i + j * n + n, k, 0);
    for (int i = 0; i < k; i++)
        update_flow();
    cout << total_cost << endl;
}
